import uuid

import anthropic
from fastapi import BackgroundTasks, FastAPI, HTTPException

client = anthropic.Anthropic(timeout=900.0)  # a worker can wait longer than a chat request
app = FastAPI()
jobs = {}  # job_id -> status and result; use a database and a real queue (Celery, RQ...) in production


def run_report(job_id, text):
    try:
        with client.messages.stream(  # long output: always stream
            model="claude-opus-5-5",
            max_tokens=64000,
            messages=[{"role": "user", "content": f"Write a detailed report on:\n{text}"}],
        ) as stream:
            final = stream.get_final_message()
        status = "done" if final.stop_reason == "end_turn" else final.stop_reason
        result = "".join(b.text for b in final.content if b.type == "text")
        jobs[job_id] = {"status": status, "result": result}
    except anthropic.APIError as e:
        jobs[job_id] = {"status": "failed", "result": type(e).__name__}


@app.post("/reports")
def create_report(text: str, background: BackgroundTasks):
    job_id = str(uuid.uuid4())
    jobs[job_id] = {"status": "running", "result": None}
    background.add_task(run_report, job_id, text)
    return {"job_id": job_id}  # answer at once; the UI polls GET /reports/{job_id}


@app.get("/reports/{job_id}")
def get_report(job_id: str):
    if job_id not in jobs:
        raise HTTPException(status_code=404, detail="Unknown job")
    return jobs[job_id]

import time


class CircuitBreaker:
    """After `threshold` failures in a row, skip the AI call for `cooldown` seconds."""

    def __init__(self, threshold=5, cooldown=60):
        self.threshold = threshold
        self.cooldown = cooldown
        self.failures = 0
        self.opened_at = None

    def allow(self):
        if self.opened_at is None:
            return True
        if time.monotonic() - self.opened_at >= self.cooldown:
            self.opened_at = None  # cooldown over: let calls try again
            self.failures = 0
            return True
        return False  # open: use the fallback without calling the API

    def record(self, ok):
        if ok:
            self.failures = 0
            return
        self.failures += 1
        if self.failures >= self.threshold:
            self.opened_at = time.monotonic()


breaker = CircuitBreaker()


def reply(messages, call_claude, fallback):
    if not breaker.allow():
        return fallback
    try:
        text = call_claude(messages)
    except Exception:
        breaker.record(ok=False)
        return fallback
    breaker.record(ok=True)
    return text

import json
from collections import defaultdict


def cost_by_feature(lines):
    """Sum requests and cost per feature from the JSON log lines of tracked_call."""
    totals = defaultdict(lambda: {"requests": 0, "cost_usd": 0.0, "cut_or_refused": 0})
    for line in lines:
        entry = json.loads(line)
        t = totals[entry["feature"]]
        t["requests"] += 1
        t["cost_usd"] += entry["cost_usd"]
        if entry["stop_reason"] in ("max_tokens", "refusal"):
            t["cut_or_refused"] += 1  # paid, but not a completed task
    for t in totals.values():
        done = t["requests"] - t["cut_or_refused"]
        t["cost_per_completed_task"] = t["cost_usd"] / done if done else None
    return dict(totals)


with open("ai_usage.log", encoding="utf-8") as f:
    for feature, t in sorted(cost_by_feature(f).items(), key=lambda kv: -kv[1]["cost_usd"]):
        print(feature, t)
